// Collision follows the car's actual transform, including rotation and scale.
function carLocal(x,z){const dx=x-car.position.x,dz=z-car.position.z,c=Math.cos(car.rotation.y),s=Math.sin(car.rotation.y);return{x:(c*dx-s*dz)/car.scale.x,z:(s*dx+c*dz)/car.scale.z}}
function isCarBlocking(x,z,r=.34){const q=carLocal(x,z),rx=r/car.scale.x,rz=r/car.scale.z;return Math.abs(q.x)<1.43+rx&&Math.abs(q.z)<2.3+rz}
